  <style>
    :root {
      color-scheme: dark;
      --color-bg: #0b1020;
      --color-panel: #121a30;
      --color-panel-strong: #18233f;
      --color-text: #f5f7ff;
      --color-muted-text: #b7c2df;
      --color-border: #34415f;
      --color-accent: #8fb4ff;
      --color-accent-strong: #c5d7ff;
      --color-focus: #ffd66b;
      --shadow-elevated: 0 20px 50px #030712;
      --radius-large: 22px;
      --radius-medium: 16px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
