      margin: 0 0 0.75rem;
      color: var(--color-accent-strong);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.2rem, 5vw, 4rem);
      line-height: 1.1;
    }

    .intro {
      max-width: 44rem;
      margin: 1rem 0 0;
      color: var(--color-muted-text);
      font-size: 1.05rem;
    }

    .faq-list {
      display: grid;
      gap: 1rem;
    }

    .example {
      border: 1px solid var(--color-border);
      border-radius: var(--radius-medium);
      background: linear-gradient(180deg, #131c32 0%, #10172a 100%);
      box-shadow: 0 14px 34px #040814;
      overflow: clip;
